def process(summerRainFresh, summerRainMarine, summerExceedance):
    import pandas as pd

    def corr_for(beach_label: str, rain_df: pd.DataFrame) -> float:
        # Map exceedance beach type labels to match rain labels
        ex = summerExceedance.copy()
        if beach_label == 'Fresh':
            ex = ex[ex['Beach Type Description'] == 'Fresh']
        else:
            ex = ex[ex['Beach Type Description'] == 'Marine']

        merged = ex.merge(
            rain_df[['Year', 'month', 'rain']],
            on=['Year', 'month'],
            how='inner',
            validate='one_to_one'
        )
        # Pearson correlation across the 9 (year,month) points
        return float(merged['rain'].corr(merged['exceed_rate']))

    corr_fresh = corr_for('Fresh', summerRainFresh)
    corr_marine = corr_for('Marine', summerRainMarine)

    out = pd.DataFrame([
        {'beachType': 'Freshwater', 'correlation': corr_fresh},
        {'beachType': 'Marine', 'correlation': corr_marine},
    ])
    out['absCorrelation'] = out['correlation'].abs()
    out['higher'] = out['absCorrelation'] == out['absCorrelation'].max()
    return out.sort_values('absCorrelation', ascending=False).reset_index(drop=True)
